namespace Og.Core.Model;

/// <summary>
/// One mortal being. A character is born, lives, and ends exactly once. The end
/// is final: everything here is lost, including inventory, quest progress and
/// flags. Characters are identified only by their own id; connection handling is
/// the transport layer's concern and is not modelled here.
///
/// There are two ways to end. Most are killed. A few walk out of the door with a
/// key in their hand, and that is not a death — it is the other ending, and the
/// record keeps the difference.
/// </summary>
public sealed class Character : Creature
{
    public const int BaseArmorClass = 12;
    public const int BaseAttackStrength = 3;
    public const int StartingHitPoints = 20;

    /// <summary>
    /// What is written against a character who left through the door rather than
    /// being carried out of the world feet first.
    /// </summary>
    public const string WalkedOut = "walking out of the valley alive";

    /// <summary>Unique to this character.</summary>
    public string Id { get; }

    public DateTimeOffset BornAt { get; } = DateTimeOffset.UtcNow;
    public DateTimeOffset? DiedAt { get; private set; }
    public string? CauseOfDeath { get; private set; }

    public bool IsDead => DiedAt is not null;

    /// <summary>
    /// Finished, but standing up. Still <see cref="IsDead"/> as far as the world
    /// is concerned — one life, no return — but nobody killed them.
    /// </summary>
    public bool HasLeft => CauseOfDeath == WalkedOut;

    public int CurrentLocationId { get; set; }

    public Item? Weapon { get; set; }
    public Item? Armor { get; set; }

    /// <summary>Open-ended attributes, for anything not modelled as a field.</summary>
    public Dictionary<string, string> Attributes { get; } = [];

    /// <summary>
    /// Character-scoped state. All of it dies with the character: a new life starts
    /// with no flags, no quest progress, and nothing already fired.
    /// </summary>
    public HashSet<string> Conditions { get; } = new(StringComparer.OrdinalIgnoreCase);
    public HashSet<string> DisabledInteractions { get; } = new(StringComparer.OrdinalIgnoreCase);
    public HashSet<string> FiredInteractions { get; } = new(StringComparer.OrdinalIgnoreCase);

    public Character(string id, string name)
    {
        Id = id;
        Name = name;
        MaxHitPoints = StartingHitPoints;
        HitPoints = StartingHitPoints;
    }

    /// <summary>Rebuilds a character from storage, preserving its whole history.</summary>
    internal Character(string id, string name, DateTimeOffset bornAt, DateTimeOffset? diedAt, string? causeOfDeath)
    {
        Id = id;
        Name = name;
        BornAt = bornAt;
        DiedAt = diedAt;
        CauseOfDeath = causeOfDeath;
    }

    public override int ArmorClass => BaseArmorClass + (Armor?.Definition.ArmorClassBonus ?? 0);
    public override int AttackStrength => BaseAttackStrength + (Weapon?.Definition.AttackBonus ?? 0);
    public override int AttackDice => Weapon?.Definition.AttackDice ?? 1;

    public bool HasKey => Inventory.Any(item => item.Definition.IsKey);

    public void MarkDead(string cause)
    {
        DiedAt = DateTimeOffset.UtcNow;
        CauseOfDeath = cause;
    }

    /// <summary>
    /// Finished without dying. Stored the same way a death is, because the world
    /// holds one life per character either way and nothing may come back through
    /// that door; only the cause says which ending it was.
    /// </summary>
    public void MarkLeft()
    {
        DiedAt = DateTimeOffset.UtcNow;
        CauseOfDeath = WalkedOut;
    }

    /// <summary>Everything carried or worn, for what the corpse leaves behind.</summary>
    public IEnumerable<Item> AllPossessions()
    {
        foreach (var item in Inventory)
        {
            yield return item;
        }

        if (Weapon is not null) yield return Weapon;
        if (Armor is not null) yield return Armor;
    }

    public Item? FindItemOrEquipped(string name)
    {
        if (FindItem(name) is { } carried)
        {
            return carried;
        }

        if (Weapon is not null && Weapon.Matches(name))
        {
            return Weapon;
        }

        return Armor is not null && Armor.Matches(name) ? Armor : null;
    }
}

using Og.Core.Model;

namespace Og.Core.Runtime;

/// <summary>
/// The world's single mutator. All commands funnel through <see cref="HandleInput"/>
/// on one thread; nothing else writes world state.
/// </summary>
public sealed class GameEngine
{
    private readonly Random _random;
    private readonly IEventSink _events;
    private readonly CommandRegistry _commands = new();
    private readonly List<Session> _sessions = [];

    /// <summary>
    /// The line a room keeps its dead under. Parsed back out of the description
    /// each time, so the paragraph is rewritten rather than piled up.
    /// </summary>
    private const string MemorialHeading = "Someone died here:";

    /// <summary>
    /// The same thing for the other ending. A place is only ever one kind of
    /// place — you cannot be killed at a doorway with nothing standing in it —
    /// so no room carries both headings, and the parse below assumes that.
    /// </summary>
    private const string LeavingHeading = "Walked out of here:";

    /// <summary>How many of a place's dead it goes on naming. The oldest fade.</summary>
    private const int MemorialLength = 3;

    public World World { get; private set; }

    /// <summary>
    /// Puts a different world under the people already in it.
    ///
    /// Safe because nothing holds on to a place: characters carry a location
    /// number and every command resolves it afresh. Anyone standing somewhere the
    /// new world does not have is moved to where people begin.
    ///
    /// Must be called on the world's own thread, with nothing mid-command.
    /// </summary>
    public IReadOnlyList<Session> SwapWorld(World replacement)
    {
        World = replacement;

        var displaced = new List<Session>();

        foreach (var session in _sessions)
        {
            if (World.FindLocation(session.CurrentLocationId) is not null)
            {
                continue;
            }

            session.CurrentLocationId = World.SpawnLocation;
            displaced.Add(session);
        }

        return displaced;
    }

    /// <summary>Sessions of living characters only. The dead are removed immediately.</summary>
    public IReadOnlyList<Session> Sessions => _sessions;

    /// <summary>
    /// Raised when a character is finished — killed, or walked out — so the host
    /// can close out its session and let whoever is there name another.
    /// </summary>
    public event Action<Session>? CharacterDied;

    public GameEngine(World world, IEventSink events, int seed = 0)
    {
        World = world;
        _events = events;
        _random = seed == 0 ? new Random() : new Random(seed);
        DefaultCommands.Register(_commands);
    }

    public void Emit(GameEvent gameEvent) => _events.Emit(gameEvent);

    // ---- life and death -----------------------------------------------------

    /// <summary>Births a new character into the world at the spawn location.</summary>
    public Session Enter(string name, IOutputSink output)
    {
        var character = new Character(Guid.NewGuid().ToString("n")[..12], name)
        {
            CurrentLocationId = World.SpawnLocation
        };

        GiveStartingItems(character);

        var session = new Session(character, output);
        _sessions.Add(session);

        Emit(GameEvent.For(session, EventType.CharacterBorn, ("name", name)));
        Emit(GameEvent.For(session, EventType.Arrived));

        BroadcastToLocation(session.CurrentLocationId, $"{name} appears.", except: session);
        session.Write(DescribeCurrentLocation(session));

        return session;
    }

    /// <summary>Returns an existing character to the world, exactly as it was left.</summary>
    public Session Resume(Character character, IOutputSink output)
    {
        if (character.IsDead)
        {
            throw new InvalidOperationException($"Character {character.Id} is dead and cannot return.");
        }

        if (World.FindLocation(character.CurrentLocationId) is null)
        {
            character.CurrentLocationId = World.SpawnLocation;
        }

        var session = new Session(character, output);
        _sessions.Add(session);

        Emit(GameEvent.For(session, EventType.Arrived));
        BroadcastToLocation(session.CurrentLocationId, $"{character.Name} appears.", except: session);
        session.Write(DescribeCurrentLocation(session));

        return session;
    }

    /// <summary>A living character leaving the world without dying — a disconnect.</summary>
    public void Depart(Session session)
    {
        if (!_sessions.Remove(session))
        {
            return;
        }

        Emit(GameEvent.For(session, EventType.Departed));
        BroadcastToLocation(session.CurrentLocationId, $"{session.Character.Name} fades away.", except: session);
    }

    /// <summary>
    /// The character is marked dead, drops everything it carried where it fell,
    /// and its session ends. The place it fell in keeps its name.
    /// </summary>
    public void Die(Session session, string cause)
    {
        var character = session.Character;
        var location = CurrentLocation(session);

        character.MarkDead(cause);

        var dropped = character.AllPossessions().ToList();

        if (location is not null)
        {
            location.Items.AddRange(dropped);
            Remember(location, MemorialHeading, $"{character.Name}, killed by {cause}.");
        }

        character.Inventory.Clear();
        character.Weapon = null;
        character.Armor = null;

        Emit(GameEvent.For(session, EventType.Death,
            ("cause", cause),
            ("name", character.Name),
            ("lifetime_seconds", ((int)(DateTimeOffset.UtcNow - character.BornAt).TotalSeconds).ToString()),
            ("dropped", string.Join(", ", dropped.Select(item => item.Name)))));

        BroadcastToLocation(session.CurrentLocationId,
            $"{character.Name} is killed by {cause}.", except: session);

        if (dropped.Count > 0)
        {
            BroadcastToLocation(session.CurrentLocationId,
                $"Their belongings fall to the ground: {string.Join(", ", dropped.Select(item => item.Name))}.",
                except: session);
        }

        session.Write($"\nYou are killed by {cause}.\n\nThat is the end of {character.Name}.");

        _sessions.Remove(session);
        CharacterDied?.Invoke(session);
    }

    /// <summary>
    /// Walking out. The other ending, and the only one anybody chooses.
    ///
    /// It is as final as being killed — one life, no way back in — but it is not
    /// a death, and the differences are the whole point of it: nothing is
    /// dropped, because what you earned goes out of the world with you; the door
    /// keeps your name where the ground would have kept your corpse; and what is
    /// written against you afterwards says you left on your own feet.
    ///
    /// Before this existed, finishing this world got you a line of congratulation
    /// and left you standing in it with nothing further to do. Someone did that
    /// twice in one night and then asked, out loud, what happens now.
    /// </summary>
    public void Leave(Session session)
    {
        var character = session.Character;
        var location = CurrentLocation(session);
        var carried = character.AllPossessions().Select(item => item.Name).ToList();
        var lifetime = (int)(DateTimeOffset.UtcNow - character.BornAt).TotalSeconds;

        character.MarkLeft();

        if (location is not null)
        {
            Remember(location, LeavingHeading, $"{character.Name}, who got out.");
        }

        Emit(GameEvent.For(session, EventType.Escaped,
            ("name", character.Name),
            ("lifetime_seconds", lifetime.ToString()),
            ("carried", string.Join(", ", carried))));

        BroadcastToWorld($"{character.Name} has walked out of the valley.", except: session);

        session.Write(
            "You go through. The daylight is flat and grey and enormous, and the door swings to behind you "
            + "with a sound the rock takes and keeps.\n\n"
            + (carried.Count > 0
                ? $"You are still carrying: {string.Join(", ", carried)}. Nobody takes it off you.\n\n"
                : "You are carrying nothing at all, and you are still going.\n\n")
            + $"That is the end of {character.Name}, who was not killed.");

        _sessions.Remove(session);
        CharacterDied?.Invoke(session);
    }

    /// <summary>
    /// Writes what happened to people into the ground it happened on. A pile of
    /// gear on a floor says nothing about whose it was; whoever walks in next
    /// should be able to find that out from the room rather than from a god. Kept
    /// to the last few names so a busy room does not turn into a ledger, and
    /// stored in the description because that is the one thing a place carries
    /// across restarts.
    /// </summary>
    private static void Remember(Location location, string heading, string entry)
    {
        var description = location.Description;
        var names = new List<string>();
        var index = description.IndexOf(heading, StringComparison.Ordinal);

        if (index >= 0)
        {
            names.AddRange(description[(index + heading.Length)..]
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries));

            description = description[..index].TrimEnd();
        }

        names.Add(entry);

        if (names.Count > MemorialLength)
        {
            names.RemoveRange(0, names.Count - MemorialLength);
        }

        location.Description = $"{description}\n\n{heading}\n{string.Join("\n", names)}";
    }

    private void GiveStartingItems(Character character)
    {
        foreach (var name in World.StartingItems)
        {
            if (World.CreateItem(name) is not { } item)
            {
                continue;
            }

            switch (item.Kind)
            {
                case ItemKind.Weapon when character.Weapon is null:
                    character.Weapon = item;
                    break;

                case ItemKind.Armor when character.Armor is null:
                    character.Armor = item;
                    break;

                default:
                    character.Inventory.Add(item);
                    break;
            }
        }
    }

    public Location? CurrentLocation(Session session) => World.FindLocation(session.CurrentLocationId);

    // ---- input ---------------------------------------------------------------

    public void HandleInput(Session session, string rawCommand)
    {
        if (string.IsNullOrWhiteSpace(rawCommand) || session.Character.IsDead)
        {
            return;
        }

        var raw = rawCommand.Trim();
        var command = TriggerMatcher.Normalize(rawCommand);

        Emit(GameEvent.For(session, EventType.Command, ("text", raw)));

        var result = _commands.Execute(this, session, command, raw);

        if (result.Status == CommandStatus.Done)
        {
            return;
        }

        // A verb that came to nothing still carries on to the place the player is
        // standing in: the room may know what the engine does not.
        if (TryInteractions(session, command))
        {
            return;
        }

        // Nothing anywhere had an answer. Recorded rather than discarded, with
        // whatever the engine was going to say about it.
        Emit(GameEvent.For(session, EventType.UnparsedCommand,
            ("text", raw),
            ("kind", result.Status == CommandStatus.Futile ? "no effect" : "unrecognised"),
            ("refusal", result.Message ?? "")));

        session.Write(result.Message ?? "Nothing happens.");
    }

    private bool TryInteractions(Session session, string command)
    {
        var location = CurrentLocation(session);

        if (location is null)
        {
            return false;
        }

        // Snapshot: an action may enable or disable interactions mid-iteration.
        foreach (var interaction in location.Interactions.ToArray())
        {
            if (!interaction.IsEligible(World, session) || !interaction.MatchesTrigger(command))
            {
                continue;
            }

            Emit(GameEvent.For(session, EventType.InteractionFired,
                ("interaction", interaction.Id ?? "(anonymous)"),
                ("command", command)));

            foreach (var action in interaction.Actions)
            {
                Execute(session, action);
            }

            if (interaction.Once && interaction.Id is not null)
            {
                session.Character.FiredInteractions.Add(interaction.Id);
            }

            return true;
        }

        return false;
    }

    // ---- interaction actions --------------------------------------------------

    private void Execute(Session session, WorldAction action)
    {
        switch (action.Kind)
        {
            case ActionKind.Describe:
                session.Write(action.FirstParameter);
                break;

            case ActionKind.AddItems:
                foreach (var name in action.Parameters)
                {
                    if (World.CreateItem(name) is { } item)
                    {
                        session.Character.Inventory.Add(item);
                        session.Write($"You received {item.Name}.");
                        Emit(GameEvent.For(session, EventType.ItemPickedUp, ("item", item.Name)));
                    }
                }
                break;

            case ActionKind.RemoveItems:
                foreach (var name in action.Parameters)
                {
                    if (session.Character.FindItem(name) is { } item)
                    {
                        session.Character.Inventory.Remove(item);
                        Emit(GameEvent.For(session, EventType.ItemDropped, ("item", item.Name)));
                    }
                }
                break;

            // A place that can mend someone. "full" or a number of hit points.
            case ActionKind.Heal:
            {
                var character = session.Character;
                var missing = character.MaxHitPoints - character.HitPoints;

                var wanted = string.Equals(action.FirstParameter, "full", StringComparison.OrdinalIgnoreCase)
                    ? missing
                    : action.FirstParameterAsInt;

                var healed = Math.Clamp(wanted, 0, missing);
                character.HitPoints += healed;

                session.Write(healed > 0
                    ? $"HP: {character.HitPoints}/{character.MaxHitPoints}"
                    : "You were not carrying any hurt worth mending.");
                break;
            }

            case ActionKind.ChangeLocation:
                MoveTo(session, action.FirstParameterAsInt);
                break;

            case ActionKind.SetLocationDescription:
                if (World.FindLocation(action.FirstParameterAsInt) is { } target
                    && action.Parameters.Length > 1)
                {
                    target.Description = action.Parameters[1];
                }
                break;

            case ActionKind.EnableInteraction:
                SetInteractionDisabled(session, action, disabled: false);
                break;

            case ActionKind.DisableInteraction:
                SetInteractionDisabled(session, action, disabled: true);
                break;

            case ActionKind.AddCondition:
                ConditionSet(session, action.Scope).Add(action.FirstParameter);
                break;

            case ActionKind.RemoveCondition:
                ConditionSet(session, action.Scope).Remove(action.FirstParameter);
                break;
        }
    }

    private HashSet<string> ConditionSet(Session session, Scope scope) =>
        scope == Scope.World ? World.Conditions : session.Character.Conditions;

    private void SetInteractionDisabled(Session session, WorldAction action, bool disabled)
    {
        var id = action.FirstParameter;

        if (action.Scope == Scope.Player)
        {
            if (disabled)
            {
                session.Character.DisabledInteractions.Add(id);
            }
            else
            {
                session.Character.DisabledInteractions.Remove(id);
            }

            return;
        }

        if (World.FindInteraction(id) is { } interaction)
        {
            interaction.DisabledForWorld = disabled;
        }
    }

    // ---- movement --------------------------------------------------------------

    public void MoveTo(Session session, int locationId)
    {
        var destination = World.FindLocation(locationId);

        if (destination is null)
        {
            Emit(GameEvent.For(session, EventType.BlockedMovement, ("target", locationId.ToString())));
            session.Write("You can't go that way.");
            return;
        }

        var from = session.CurrentLocationId;

        BroadcastToLocation(from, $"{session.Character.Name} leaves.", except: session);
        session.PreviousLocationId = from;
        session.CurrentLocationId = destination.Id;
        BroadcastToLocation(destination.Id, $"{session.Character.Name} arrives.", except: session);

        Emit(GameEvent.For(session, EventType.Movement,
            ("from", from.ToString()), ("to", destination.Id.ToString())));

        session.Write(DescribeCurrentLocation(session));
    }

    // ---- combat ------------------------------------------------------------------

    public void Attack(Session session)
    {
        var location = CurrentLocation(session);

        if (location?.Monster is not { } monster || !monster.IsAlive)
        {
            session.Write("There is nothing to attack here.");
            return;
        }

        var character = session.Character;
        var attackRoll = _random.Next(1, 21) + character.AttackStrength;
        var damage = _random.Next(1, character.AttackDice + 1) + character.AttackStrength;

        if (monster.ReceiveAttack(attackRoll, damage))
        {
            session.Write("You hit!");
            Emit(GameEvent.For(session, EventType.Combat,
                ("target", monster.Name), ("result", "hit"), ("damage", damage.ToString())));

            if (!monster.IsAlive)
            {
                session.Write($"The {monster.Name} has died.");
                BroadcastToLocation(location.Id, $"{character.Name} slays the {monster.Name}.", except: session);

                location.Items.AddRange(monster.Inventory);
                Emit(GameEvent.For(session, EventType.MonsterSlain, ("monster", monster.Name)));
                location.Monster = null;
                location.ClearedAt = DateTimeOffset.UtcNow;

                if (location.Items.Count > 0)
                {
                    session.Write($"On the ground: {string.Join(", ", location.Items.Select(item => item.Name))}.");
                }

                return;
            }
        }
        else
        {
            session.Write("You missed!");
            Emit(GameEvent.For(session, EventType.Combat, ("target", monster.Name), ("result", "miss")));
        }

        var monsterRoll = _random.Next(1, 21) + monster.AttackStrength;
        var monsterDamage = _random.Next(1, monster.AttackDice + 1) + monster.AttackStrength;

        if (character.ReceiveAttack(monsterRoll, monsterDamage))
        {
            session.Write($"You were hit! HP: {character.HitPoints}/{character.MaxHitPoints}");

            if (!character.IsAlive)
            {
                Die(session, $"a {monster.Name}");
            }
        }
        else
        {
            session.Write($"The {monster.Name} missed!");
        }
    }

    /// <summary>
    /// Brings back creatures whose time has passed. Called on the world's own
    /// thread, so nothing else is mid-way through reading the map.
    /// </summary>
    public void Repopulate()
    {
        foreach (var location in World.Repopulate(DateTimeOffset.UtcNow))
        {
            Emit(new GameEvent(Actor.Engine, EventType.MonsterReturned, null, location.Id,
                new Dictionary<string, string> { ["monster"] = location.Monster!.Name }));

            BroadcastToLocation(location.Id,
                $"Something moves. {location.Monster!.Description}");
        }
    }

    // ---- description ----------------------------------------------------------------

    public string DescribeCurrentLocation(Session session)
    {
        var location = CurrentLocation(session);

        if (location is null)
        {
            return "You are nowhere.";
        }

        var parts = new List<string> { location.Description };

        if (location.Monster is { IsAlive: true } monster)
        {
            parts.Add(monster.Description);
        }

        if (location.Items.Count > 0)
        {
            parts.Add($"On the ground: {string.Join(", ", location.Items.Select(item => item.Name))}.");
        }

        var others = PlayersAt(location.Id).Where(other => other != session).ToList();

        if (others.Count > 0)
        {
            parts.Add($"Also here: {string.Join(", ", others.Select(other => other.Character.Name))}.");
        }

        var directions = location.OpenDirections()
            .Select(direction => direction.ToString().ToLowerInvariant())
            .ToList();

        if (directions.Count > 0)
        {
            parts.Add($"There is a passage to the {Join(directions)}.");
        }

        if (location.IsExit)
        {
            parts.Add("This is the way out. Walking through it ends this life; the word is exit.");
        }

        return string.Join("\n\n", parts);
    }

    private static string Join(IReadOnlyList<string> values) => values.Count switch
    {
        1 => values[0],
        2 => $"{values[0]} and {values[1]}",
        _ => $"{string.Join(", ", values.Take(values.Count - 1))}, and {values[^1]}"
    };

    // ---- broadcast --------------------------------------------------------------------

    public IEnumerable<Session> PlayersAt(int locationId) =>
        _sessions.Where(session => session.CurrentLocationId == locationId);

    public void BroadcastToLocation(int locationId, string message, Session? except = null)
    {
        foreach (var session in PlayersAt(locationId).ToArray())
        {
            if (session != except)
            {
                session.Write(message);
            }
        }
    }

    public void BroadcastToWorld(string message, Session? except = null)
    {
        foreach (var session in _sessions.ToArray())
        {
            if (session != except)
            {
                session.Write(message);
            }
        }
    }
}

using Og.Core.Model;

namespace Og.Core.Runtime;

/// <summary>
/// The verbs the engine knows. A handler returns Done only when something
/// actually happened; when it recognises the words but can do nothing with them
/// it returns Futile, and the command carries on to the place the player is in.
/// </summary>
public static class DefaultCommands
{
    private static readonly (string Word, Direction Direction)[] DirectionWords =
    [
        ("north", Direction.North),
        ("east", Direction.East),
        ("south", Direction.South),
        ("west", Direction.West)
    ];

    /// <summary>Words people put between a verb and what they mean. Stripped, in order.</summary>
    private static readonly string[] Fillers = ["to", "the", "towards", "toward", "into", "my", "a"];

    /// <summary>Ways of saying "all of it" when there is a pile on the floor.</summary>
    private static readonly HashSet<string> Everything = new(StringComparer.OrdinalIgnoreCase)
    {
        "all", "everything", "all of it", "all of them", "it all", "all items",
        "everything here", "lot", "them all", "whats here", "what is here"
    };

    /// <summary>
    /// Remembered on the character once the door has told them what going through
    /// it costs. Character-scoped, so it dies with them and every new life is
    /// warned afresh.
    /// </summary>
    private const string WarnedAtTheDoor = "warned-at-the-door";

    public static void Register(CommandRegistry registry)
    {
        RegisterMovement(registry);
        RegisterObservation(registry);
        RegisterInventory(registry);
        RegisterCombat(registry);
        RegisterSpeech(registry);
    }

    private static void RegisterMovement(CommandRegistry registry)
    {
        Move(Direction.North, "go north", "north", "n");
        Move(Direction.East, "go east", "east", "e");
        Move(Direction.South, "go south", "south", "s");
        Move(Direction.West, "go west", "west", "w");

        void Move(Direction direction, params string[] forms) =>
            registry.RegisterExact((engine, session, _) =>
            {
                var location = engine.CurrentLocation(session);

                if (location is null)
                {
                    return CommandResult.NotHandled;
                }

                var target = location.Exit(direction);

                // A wall is worth knowing about, but the room may still answer.
                if (target <= 0)
                {
                    engine.Emit(GameEvent.For(session, EventType.BlockedMovement,
                        ("direction", direction.ToString().ToLowerInvariant())));

                    return CommandResult.Futile("You can't go that way. " + Ways(location));
                }

                engine.MoveTo(session, target);
                return CommandResult.Done();
            }, forms);

        // "go soith" is not a mystery to anyone but a parser. Whatever follows a
        // going-word is measured against the four directions, and the nearest wins
        // so long as it is nearer than all the others. When nothing is close, the
        // refusal at least says which ways are open.
        registry.RegisterPrefix((engine, session, argument) =>
        {
            var location = engine.CurrentLocation(session);

            if (location is null)
            {
                return CommandResult.NotHandled;
            }

            var direction = NearestDirection(StripFillers(TriggerMatcher.Normalize(argument)));

            if (direction is null)
            {
                return CommandResult.Futile(Ways(location));
            }

            var target = location.Exit(direction.Value);

            if (target <= 0)
            {
                engine.Emit(GameEvent.For(session, EventType.BlockedMovement,
                    ("direction", direction.Value.ToString().ToLowerInvariant())));

                return CommandResult.Futile("You can't go that way. " + Ways(location));
            }

            engine.MoveTo(session, target);
            return CommandResult.Done();
        }, "go", "walk", "move", "head", "travel", "run");

        // Nobody standing in front of a troll should have to work out the compass.
        // Running takes you back the way you came if that way is open, and out by
        // whatever door there is otherwise. Nothing swings at your back as you go:
        // this is the same retreat as walking out, said the way people say it.
        registry.RegisterExact((engine, session, _) =>
        {
            var location = engine.CurrentLocation(session);

            if (location is null)
            {
                return CommandResult.NotHandled;
            }

            var open = location.OpenDirections().ToList();

            if (open.Count == 0)
            {
                return CommandResult.Futile("There is nowhere to run to.");
            }

            var back = open.FirstOrDefault(
                direction => location.Exit(direction) == session.PreviousLocationId,
                open[0]);

            session.Write(location.Monster is { IsAlive: true } monster
                ? $"You break off and go. The {monster.Name} does not follow."
                : "You go, quickly.");

            engine.MoveTo(session, location.Exit(back));
            return CommandResult.Done();
        }, "flee", "run away", "run for it", "retreat", "back off", "get out",
           "get out of here", "back away", "withdraw", "leg it");
    }

    private static string StripFillers(string text)
    {
        foreach (var filler in Fillers)
        {
            if (text.StartsWith(filler + " ", StringComparison.Ordinal))
            {
                text = text[(filler.Length + 1)..];
            }
        }

        return text;
    }

    private static string Ways(Location location)
    {
        var open = location.OpenDirections()
            .Select(direction => direction.ToString().ToLowerInvariant())
            .ToList();

        return open.Count == 0
            ? "There is nowhere to go from here."
            : $"You can go {string.Join(", ", open)}.";
    }

    private static Direction? NearestDirection(string word)
    {
        if (word.Length == 0)
        {
            return null;
        }

        foreach (var (candidate, direction) in DirectionWords)
        {
            if (word == candidate || (word.Length == 1 && candidate[0] == word[0]))
            {
                return direction;
            }
        }

        var nearest = TriggerMatcher.Nearest(
            word,
            DirectionWords.Select(entry => entry.Word),
            word.Length <= 4 ? 1 : 2);

        return nearest is null
            ? null
            : DirectionWords.First(entry => entry.Word == nearest).Direction;
    }

    private static void RegisterObservation(CommandRegistry registry)
    {
        // The world is a bare prompt otherwise. This says what the engine itself
        // understands, and then says that the engine is not the whole of it.
        registry.RegisterExact((_, session, _) =>
        {
            session.Write("To move: north, south, east, west. To leave a fight: flee.");
            session.Write("To see: look, search <thing>, exits, examine <thing>, inventory, health, who.");
            session.Write("To act: take <thing>, take all, drop <thing>, give <thing>, equip <thing>, use <thing>, rest, attack.");
            session.Write("To speak: say <words>, yell <words>, whisper <name> <words>, talk to <someone>.");
            session.Write("To finish: exit, at the door, with a key. That is the end of the character, and it will say so before it takes you.");
            session.Write("When none of those fit, write plainly what you mean to do. Places understand more than this list does.");
            return CommandResult.Done();
        }, "help", "commands", "verbs", "how do i play", "what do i do", "how does this work");

        registry.RegisterExact((engine, session, _) =>
        {
            session.Write(engine.DescribeCurrentLocation(session));
            return CommandResult.Done();
        }, "look", "look around", "where am i", "where is this", "l");

        // Searching is not looking. It reaches the room afterwards, so a place with
        // something buried in it gets its chance to say so — and when the room has
        // no answer for a bare "search", the refusal says what kind of thing would
        // work instead of claiming there is nothing here.
        registry.RegisterExact((engine, session, _) =>
        {
            session.Write(engine.DescribeCurrentLocation(session));
            return CommandResult.Futile(
                "Turning things over at random turns up nothing. A search wants an object: "
                + "name something this place has already mentioned, and go through that.");
        }, "search", "search the room", "search around", "explore", "investigate", "look closer", "look again");

        registry.RegisterExact((engine, session, _) =>
        {
            var location = engine.CurrentLocation(session);

            if (location is null)
            {
                return CommandResult.NotHandled;
            }

            session.Write(Ways(location));

            if (location.IsExit)
            {
                session.Write("This is the way out, for anyone holding a key — and the end of this life.");
            }

            return CommandResult.Done();
        }, "exits", "directions", "which way", "where can i go", "where do i go", "find exit", "where is the exit");

        // Weariness is the commonest thing anyone asks this world for. Most places
        // cannot answer it, and should say so rather than say nothing — but the
        // refusal still carries on to the room, in case the room can.
        registry.RegisterExact((_, _, _) =>
            CommandResult.Futile("There is nowhere to rest here. Not every place will have you."),
            "rest", "sleep", "nap", "sit", "sit down", "lie down", "make camp", "take a rest", "recover");

        registry.RegisterExact((_, _, _) =>
            CommandResult.Futile("Nothing here closes wounds. A potion might, if you are carrying one."),
            "heal", "heal me", "cure me", "bandage");

        registry.RegisterExact((_, session, _) =>
        {
            var character = session.Character;
            session.Write($"HP: {character.HitPoints}/{character.MaxHitPoints}");
            return CommandResult.Done();
        }, "health", "hit points", "hp");

        registry.RegisterExact((engine, session, _) =>
        {
            var names = engine.Sessions.Select(other => other.Character.Name).Order();
            session.Write($"Here in this world: {string.Join(", ", names)}");
            return CommandResult.Done();
        }, "who", "players");

        // What is lying at your feet can be looked at before it is picked up — and
        // so can whatever is standing in the room with you. Someone who types
        // "look at goblin" with a goblin in front of them should not be told they
        // aren't carrying one: every creature in this world was written a
        // description, and until now there was no word that reached it.
        registry.RegisterPrefix((engine, session, argument) =>
        {
            var location = engine.CurrentLocation(session);

            var found = session.Character.FindItemOrEquipped(argument)
                        ?? location?.Items.FirstOrDefault(candidate => candidate.Matches(argument));

            if (found is not null)
            {
                session.Write(found.Description);
                return CommandResult.Done();
            }

            if (location?.Monster is { IsAlive: true } monster && monster.Matches(argument))
            {
                session.Write(monster.Description);
                session.Write($"HP: {monster.HitPoints}/{monster.MaxHitPoints}");
                return CommandResult.Done();
            }

            return CommandResult.Futile($"You aren't carrying a {argument}, and there is no {argument} here.");
        }, "describe", "look at", "examine", "inspect");
    }

    private static void RegisterInventory(CommandRegistry registry)
    {
        registry.RegisterExact((_, session, _) =>
        {
            var character = session.Character;

            session.Write($"Weapon: {character.Weapon?.Name ?? "none equipped"}");
            session.Write($"Armor: {character.Armor?.Name ?? "none equipped"}");
            session.Write(character.Inventory.Count == 0
                ? "Inventory: empty"
                : "Inventory: " + string.Join(", ", character.Inventory.Select(item => item.Name)));

            return CommandResult.Done();
        }, "inventory", "items", "i");

        registry.RegisterPrefix((_, session, argument) =>
        {
            var character = session.Character;
            var item = character.FindItem(argument);

            if (item is null)
            {
                return CommandResult.Futile($"You aren't carrying a {argument}.");
            }

            switch (item.Kind)
            {
                case ItemKind.Weapon:
                    if (character.Weapon is { } oldWeapon) character.Inventory.Add(oldWeapon);
                    character.Weapon = item;
                    break;

                case ItemKind.Armor:
                    if (character.Armor is { } oldArmor) character.Inventory.Add(oldArmor);
                    character.Armor = item;
                    break;

                default:
                    return CommandResult.Futile($"You can't equip the {item.Name}.");
            }

            character.Inventory.Remove(item);
            session.Write($"You equipped the {item.Name}.");
            return CommandResult.Done();
        }, "equip", "wield", "wear", "put on");

        registry.RegisterPrefix((_, session, argument) =>
        {
            var character = session.Character;
            var item = character.FindItem(argument);

            if (item is null)
            {
                return CommandResult.Futile($"You aren't carrying a {argument}.");
            }

            if (item.Kind != ItemKind.Consumable)
            {
                // The room may well know what this thing is for, even though the
                // engine does not.
                return CommandResult.Futile($"Nothing happens when you use the {item.Name}.");
            }

            var healed = Math.Min(item.Definition.HealAmount, character.MaxHitPoints - character.HitPoints);
            character.HitPoints += healed;

            if (item.Definition.ConsumedOnUse)
            {
                character.Inventory.Remove(item);
            }

            session.Write($"You used the {item.Name}. HP: {character.HitPoints}/{character.MaxHitPoints}");
            return CommandResult.Done();
        }, "use", "drink", "eat");

        // Handing a thing over. The engine has no giving in it and no one to give
        // to; this exists so that the sentence is a recognised shape, checked
        // against what you are actually holding, and then passed on to the room,
        // where somebody may be sitting who will take the thing. Somebody typed
        // "give bone" three times at a woman who trades, and got "Nothing happens."
        registry.RegisterPrefix((_, session, argument) =>
        {
            var item = session.Character.FindItemOrEquipped(argument);

            return item is null
                ? CommandResult.Futile($"You aren't carrying a {argument}.")
                : CommandResult.Futile($"There is nobody here who wants the {item.Name}.");
        }, "give", "offer", "hand", "hand over", "hand to", "show", "sell", "trade");

        registry.RegisterPrefix((engine, session, argument) =>
        {
            var location = engine.CurrentLocation(session);

            if (location is null)
            {
                return CommandResult.Futile($"There is no {argument} here to take.");
            }

            // Standing over what the dead left behind, nobody wants to type seven
            // lines to pick it up.
            if (argument.Trim().Length == 0 || Everything.Contains(StripFillers(TriggerMatcher.Normalize(argument))))
            {
                if (location.Items.Count == 0)
                {
                    return CommandResult.Futile("There is nothing here to take.");
                }

                foreach (var lying in location.Items.ToArray())
                {
                    Take(engine, session, location, lying);
                }

                return CommandResult.Done();
            }

            var item = location.Items.FirstOrDefault(candidate => candidate.Matches(argument));

            if (item is null)
            {
                // Reaching for something already in your hands is a misunderstanding
                // worth clearing up, not a wall.
                if (session.Character.FindItemOrEquipped(argument) is { } carried)
                {
                    return CommandResult.Futile($"You already have the {carried.Name}.");
                }

                return CommandResult.Futile($"There is no {argument} here to take.");
            }

            Take(engine, session, location, item);
            return CommandResult.Done();
        }, "take", "pick up", "get", "grab", "loot", "gather");

        registry.RegisterPrefix((engine, session, argument) =>
        {
            var location = engine.CurrentLocation(session);
            var item = session.Character.FindItem(argument);

            if (location is null || item is null)
            {
                return CommandResult.Futile($"You aren't carrying a {argument}.");
            }

            session.Character.Inventory.Remove(item);
            location.Items.Add(item);
            session.Write($"You drop the {item.Name}.");
            engine.BroadcastToLocation(location.Id, $"{session.Character.Name} drops the {item.Name}.", except: session);
            engine.Emit(GameEvent.For(session, EventType.ItemDropped, ("item", item.Name)));
            return CommandResult.Done();
        }, "drop");
    }

    private static void Take(GameEngine engine, Session session, Location location, Item item)
    {
        location.Items.Remove(item);
        session.Character.Inventory.Add(item);
        session.Write($"You take the {item.Name}.");
        engine.BroadcastToLocation(location.Id, $"{session.Character.Name} takes the {item.Name}.", except: session);
        engine.Emit(GameEvent.For(session, EventType.ItemPickedUp, ("item", item.Name)));
    }

    private static void RegisterCombat(CommandRegistry registry)
    {
        CommandResult Strike(GameEngine engine, Session session, string argument)
        {
            var location = engine.CurrentLocation(session);

            if (location?.Monster is not { IsAlive: true } monster)
            {
                return CommandResult.Futile("There is nothing to attack here.");
            }

            // Naming what is in front of you is the commonest way to say it, and
            // people misspell it with something breathing down their neck. A near
            // miss is taken as the only creature in the room. Anything further off
            // is refused — but told what is actually standing there.
            if (argument.Length > 0 && !monster.Matches(argument))
            {
                var target = StripFillers(TriggerMatcher.Normalize(argument));

                var near = target.Length >= 4
                    && (TriggerMatcher.Distance(target, monster.Name) <= 2
                        || monster.Name.Split(' ').Any(word =>
                            word.Length >= 4 && TriggerMatcher.Distance(target, word) <= 2));

                if (!near)
                {
                    return CommandResult.Futile(
                        $"There is no {argument} here to attack. The {monster.Name} is what is in front of you.");
                }
            }

            engine.Attack(session);
            return CommandResult.Done();
        }

        registry.RegisterExact(Strike, "attack", "fight", "kill", "stab");
        registry.RegisterPrefix(Strike, "attack", "fight", "kill", "stab", "attack the", "kill the");

        // The door.
        //
        // Walking out is the only ending anybody chooses, and it is as final as
        // the other one: the character is finished and nothing comes back in. So
        // it is asked for twice. The first time the door explains exactly what it
        // costs and does not open; the second time it opens. The remembering is
        // character-scoped, so it dies with them and the next life is warned too.
        //
        // Soft words — "leave" — never commit, however often they are typed. Only
        // the words that can only mean this do.
        CommandResult AtTheDoor(GameEngine engine, Session session, bool committing)
        {
            var location = engine.CurrentLocation(session);

            if (location is null || !location.IsExit)
            {
                return CommandResult.Futile("Sadly, this is not the exit.");
            }

            if (!session.Character.HasKey)
            {
                return CommandResult.Futile(
                    "The door is locked and you are not carrying the key. The troll in the passage keeps one.");
            }

            if (!committing || session.Character.Conditions.Add(WarnedAtTheDoor))
            {
                session.Write(
                    "Your hand is on it and it gives — unlocked, unbarred, a half-inch of cold daylight and a "
                    + "road going away downhill.\n\n"
                    + "Be sure. This is the edge of the world that was made for you. Nothing was built out "
                    + "there and nothing is waiting, and there is no door back in. Whoever goes through is "
                    + "finished here, carrying everything they earned. It is not a death — it is the other "
                    + "way out of this valley, and it is the better one.\n\n"
                    + "Say the word again and you go: exit.");

                return CommandResult.Done();
            }

            engine.Leave(session);
            return CommandResult.Done();
        }

        registry.RegisterExact((engine, session, _) => AtTheDoor(engine, session, committing: true),
            "exit", "escape", "walk out", "step through", "through the door", "walk out of the valley");

        registry.RegisterExact((engine, session, _) => AtTheDoor(engine, session, committing: false),
            "leave", "leave here", "get away", "go home");
    }

    private static void RegisterSpeech(CommandRegistry registry)
    {
        // Speech is recorded and delivered. The world itself never answers.
        registry.RegisterPrefix((engine, session, argument) =>
        {
            engine.BroadcastToLocation(session.CurrentLocationId,
                $"{session.Character.Name} says: {argument}", except: session);
            session.Write($"You say: {argument}");
            engine.Emit(GameEvent.For(session, EventType.Speech, ("mode", "say"), ("text", argument)));
            return CommandResult.Done();
        }, "say", "speak");

        registry.RegisterPrefix((engine, session, argument) =>
        {
            engine.BroadcastToWorld($"{session.Character.Name} yells: {argument}", except: session);
            session.Write($"You yell: {argument}");
            engine.Emit(GameEvent.For(session, EventType.Speech, ("mode", "yell"), ("text", argument)));
            return CommandResult.Done();
        }, "yell", "shout");

        registry.RegisterPrefix((engine, session, argument) =>
        {
            var split = argument.IndexOf(' ');

            if (split <= 0)
            {
                return CommandResult.Futile("Whisper to whom?");
            }

            var targetName = argument[..split];
            var text = argument[(split + 1)..];
            var target = engine.Sessions.FirstOrDefault(other =>
                string.Equals(other.Character.Name, targetName, StringComparison.OrdinalIgnoreCase));

            if (target is null)
            {
                return CommandResult.Futile($"There is no {targetName} here.");
            }

            target.Write($"{session.Character.Name} whispers: {text}");
            session.Write($"You whisper to {target.Character.Name}: {text}");
            engine.Emit(GameEvent.For(session, EventType.Speech,
                ("mode", "whisper"), ("target", target.CharacterId), ("text", text)));
            return CommandResult.Done();
        }, "whisper", "tell");

        // Addressing whoever is in front of you. The engine has no conversation in
        // it and never will — but this returns Futile, so the command carries on
        // into the room, and a place that has someone worth talking to can answer
        // where the engine cannot. Before this verb existed, "talk to the goblin"
        // was not even a recognised shape of sentence.
        CommandResult Talk(GameEngine engine, Session session, string argument)
        {
            var location = engine.CurrentLocation(session);

            if (location?.Monster is { IsAlive: true } monster)
            {
                return CommandResult.Futile(
                    $"The {monster.Name} does not answer in any language you have.");
            }

            return CommandResult.Futile("There is nobody here to talk to.");
        }

        registry.RegisterPrefix(Talk, "talk to", "talk", "greet", "hail", "ask", "chat to", "chat with", "chat");
        registry.RegisterExact(Talk, "talk", "greet", "hello", "hallo", "hi", "hail", "chat", "anyone there");

        registry.RegisterPrefix((engine, session, argument) =>
        {
            session.Write("You pray.");
            engine.Emit(GameEvent.For(session, EventType.Speech, ("mode", "pray"), ("text", argument)));
            return CommandResult.Done();
        }, "pray");

        registry.RegisterExact((engine, session, _) =>
        {
            session.Write("You pray.");
            engine.Emit(GameEvent.For(session, EventType.Speech, ("mode", "pray"), ("text", "")));
            return CommandResult.Done();
        }, "pray");
    }
}

namespace Og.Core.Runtime;

public delegate CommandResult CommandHandler(GameEngine engine, Session session, string argument);

/// <summary>
/// The verbs the engine itself knows. Registered rather than hardcoded, so new
/// ones can be added without editing this file.
/// </summary>
public sealed class CommandRegistry
{
    private readonly Dictionary<string, CommandHandler> _exact = new(StringComparer.OrdinalIgnoreCase);
    private readonly List<(string Prefix, CommandHandler Handler)> _prefixes = [];

    /// <summary>
    /// Verbs never reached by guesswork. The four directions are one letter away
    /// from words that mean something else entirely — "rest" is not "west" — and
    /// moving somebody who did not ask to move is worse than not understanding them.
    /// Running is a move as well, and "flea" is not "flee".
    ///
    /// The door words are here for the same reason, only more so: ending a life
    /// nobody asked to end is the worst thing a guess could do.
    /// </summary>
    private static readonly HashSet<string> NeverCorrectedTo =
        new(StringComparer.OrdinalIgnoreCase)
        {
            "north", "south", "east", "west", "flee", "retreat", "withdraw",
            "exit", "escape", "leave"
        };

    public IReadOnlyCollection<string> Verbs => _exact.Keys;

    public void RegisterExact(CommandHandler handler, params string[] forms)
    {
        foreach (var form in forms)
        {
            _exact[form] = handler;
        }
    }

    public void RegisterPrefix(CommandHandler handler, params string[] prefixes)
    {
        foreach (var prefix in prefixes)
        {
            _prefixes.Add((prefix, handler));
        }
    }

    /// <summary>
    /// Matches on the normalised command but hands the handler the argument as the
    /// player actually typed it, so speech keeps its punctuation and capitals.
    /// </summary>
    public CommandResult Execute(GameEngine engine, Session session, string command, string raw)
    {
        if (_exact.TryGetValue(command, out var exactHandler))
        {
            return exactHandler(engine, session, "");
        }

        foreach (var (prefix, handler) in _prefixes.OrderByDescending(entry => entry.Prefix.Length))
        {
            if (!command.StartsWith(prefix + " ", StringComparison.OrdinalIgnoreCase))
            {
                continue;
            }

            var argument = raw.Length > prefix.Length && raw.StartsWith(prefix, StringComparison.OrdinalIgnoreCase)
                ? raw[prefix.Length..].Trim()
                : command[(prefix.Length + 1)..].Trim();

            return handler(engine, session, argument);
        }

        // A last chance for a slipped key. One word, one edit, and only when a
        // single verb is that close: "killl" is not a mystery, and answering it
        // with "Nothing happens" teaches people that the world is deaf.
        if (command.Length >= 4 && !command.Contains(' '))
        {
            var candidates = _exact.Keys.Where(verb =>
                verb.Length >= 4 && !verb.Contains(' ') && !NeverCorrectedTo.Contains(verb));

            if (TriggerMatcher.Nearest(command, candidates, 1) is { } corrected)
            {
                return _exact[corrected](engine, session, "");
            }
        }

        return CommandResult.NotHandled;
    }
}

using Og.Core.Model;

namespace Og.Core.Runtime;

/// <summary>
/// The verbs the engine knows. A handler returns Done only when something
/// actually happened; when it recognises the words but can do nothing with them
/// it returns Futile, and the command carries on to the place the player is in.
/// </summary>
public static class DefaultCommands
{
    private static readonly (string Word, Direction Direction)[] DirectionWords =
    [
        ("north", Direction.North),
        ("east", Direction.East),
        ("south", Direction.South),
        ("west", Direction.West)
    ];

    /// <summary>Words people put between a verb and what they mean. Stripped, in order.</summary>
    private static readonly string[] Fillers = ["to", "the", "towards", "toward", "into", "my", "a"];

    /// <summary>Ways of saying "all of it" when there is a pile on the floor.</summary>
    private static readonly HashSet<string> Everything = new(StringComparer.OrdinalIgnoreCase)
    {
        "all", "everything", "all of it", "all of them", "it all", "all items",
        "everything here", "lot", "them all", "whats here", "what is here"
    };

    /// <summary>
    /// Remembered on the character once the door has told them what going through
    /// it costs. Character-scoped, so it dies with them and every new life is
    /// warned afresh.
    /// </summary>
    private const string WarnedAtTheDoor = "warned-at-the-door";

    public static void Register(CommandRegistry registry)
    {
        RegisterMovement(registry);
        RegisterObservation(registry);
        RegisterInventory(registry);
        RegisterCombat(registry);
        RegisterSpeech(registry);
    }

    private static void RegisterMovement(CommandRegistry registry)
    {
        Move(Direction.North, "go north", "north", "n");
        Move(Direction.East, "go east", "east", "e");
        Move(Direction.South, "go south", "south", "s");
        Move(Direction.West, "go west", "west", "w");

        void Move(Direction direction, params string[] forms) =>
            registry.RegisterExact((engine, session, _) =>
            {
                var location = engine.CurrentLocation(session);

                if (location is null)
                {
                    return CommandResult.NotHandled;
                }

                var target = location.Exit(direction);

                // A wall is worth knowing about, but the room may still answer.
                if (target <= 0)
                {
                    engine.Emit(GameEvent.For(session, EventType.BlockedMovement,
                        ("direction", direction.ToString().ToLowerInvariant())));

                    return CommandResult.Futile("You can't go that way. " + Ways(location));
                }

                engine.MoveTo(session, target);
                return CommandResult.Done();
            }, forms);

        // "go soith" is not a mystery to anyone but a parser. Whatever follows a
        // going-word is measured against the four directions, and the nearest wins
        // so long as it is nearer than all the others. When nothing is close, the
        // refusal at least says which ways are open.
        registry.RegisterPrefix((engine, session, argument) =>
        {
            var location = engine.CurrentLocation(session);

            if (location is null)
            {
                return CommandResult.NotHandled;
            }

            var direction = NearestDirection(StripFillers(TriggerMatcher.Normalize(argument)));

            if (direction is null)
            {
                return CommandResult.Futile(Ways(location));
            }

            var target = location.Exit(direction.Value);

            if (target <= 0)
            {
                engine.Emit(GameEvent.For(session, EventType.BlockedMovement,
                    ("direction", direction.Value.ToString().ToLowerInvariant())));

                return CommandResult.Futile("You can't go that way. " + Ways(location));
            }

            engine.MoveTo(session, target);
            return CommandResult.Done();
        }, "go", "walk", "move", "head", "travel", "run");

        // Nobody standing in front of a troll should have to work out the compass.
        // Running takes you back the way you came if that way is open, and out by
        // whatever door there is otherwise. Nothing swings at your back as you go:
        // this is the same retreat as walking out, said the way people say it.
        registry.RegisterExact((engine, session, _) =>
        {
            var location = engine.CurrentLocation(session);

            if (location is null)
            {
                return CommandResult.NotHandled;
            }

            var open = location.OpenDirections().ToList();

            if (open.Count == 0)
            {
                return CommandResult.Futile("There is nowhere to run to.");
            }

            var back = open.FirstOrDefault(
                direction => location.Exit(direction) == session.PreviousLocationId,
                open[0]);

            session.Write(location.Monster is { IsAlive: true } monster
                ? $"You break off and go. The {monster.Name} does not follow."
                : "You go, quickly.");

            engine.MoveTo(session, location.Exit(back));
            return CommandResult.Done();
        }, "flee", "run", "run away", "run for it", "retreat", "back off", "get out",
           "get out of here", "back away", "withdraw", "leg it");
    }

    private static string StripFillers(string text)
    {
        foreach (var filler in Fillers)
        {
            if (text.StartsWith(filler + " ", StringComparison.Ordinal))
            {
                text = text[(filler.Length + 1)..];
            }
        }

        return text;
    }

    private static string Ways(Location location)
    {
        var open = location.OpenDirections()
            .Select(direction => direction.ToString().ToLowerInvariant())
            .ToList();

        return open.Count == 0
            ? "There is nowhere to go from here."
            : $"You can go {string.Join(", ", open)}.";
    }

    private static Direction? NearestDirection(string word)
    {
        if (word.Length == 0)
        {
            return null;
        }

        foreach (var (candidate, direction) in DirectionWords)
        {
            if (word == candidate || (word.Length == 1 && candidate[0] == word[0]))
            {
                return direction;
            }
        }

        var nearest = TriggerMatcher.Nearest(
            word,
            DirectionWords.Select(entry => entry.Word),
            word.Length <= 4 ? 1 : 2);

        return nearest is null
            ? null
            : DirectionWords.First(entry => entry.Word == nearest).Direction;
    }

    private static void RegisterObservation(CommandRegistry registry)
    {
        // The world is a bare prompt otherwise. This says what the engine itself
        // understands, and then says that the engine is not the whole of it.
        registry.RegisterExact((_, session, _) =>
        {
            session.Write("To move: north, south, east, west. To leave a fight: flee.");
            session.Write("To see: look, search <thing>, exits, examine <thing>, inventory, health, who.");
            session.Write("To act: take <thing>, take all, drop <thing>, give <thing>, equip <thing>, use <thing>, rest, attack.");
            session.Write("To speak: say <words>, yell <words>, whisper <name> <words>, talk to <someone>.");
            session.Write("To finish: exit, at the door, holding a key. That is the end of this character, and the door says so before it takes you.");
            session.Write("When none of those fit, write plainly what you mean to do. Places understand more than this list does.");
            return CommandResult.Done();
        }, "help", "commands", "verbs", "how do i play", "what do i do", "how does this work");

        registry.RegisterExact((engine, session, _) =>
        {
            session.Write(engine.DescribeCurrentLocation(session));
            return CommandResult.Done();
        }, "look", "look around", "where am i", "where is this", "l");

        // Searching is not looking. It reaches the room afterwards, so a place with
        // something buried in it gets its chance to say so — and when the room has
        // no answer for a bare "search", the refusal says what kind of thing would
        // work instead of claiming there is nothing here.
        registry.RegisterExact((engine, session, _) =>
        {
            session.Write(engine.DescribeCurrentLocation(session));
            return CommandResult.Futile(
                "Turning things over at random turns up nothing. A search wants an object: "
                + "name something this place has already mentioned, and go through that.");
        }, "search", "search the room", "search around", "explore", "investigate", "look closer", "look again");

        registry.RegisterExact((engine, session, _) =>
        {
            var location = engine.CurrentLocation(session);

            if (location is null)
            {
                return CommandResult.NotHandled;
            }

            session.Write(Ways(location));

            if (location.IsExit)
            {
                session.Write("This is the way out, for anyone holding a key — and the end of this life.");
            }

            return CommandResult.Done();
        }, "exits", "directions", "which way", "where can i go", "where do i go", "find exit", "where is the exit");

        // Weariness is the commonest thing anyone asks this world for. Most places
        // cannot answer it, and should say so rather than say nothing — but the
        // refusal still carries on to the room, in case the room can.
        registry.RegisterExact((_, _, _) =>
            CommandResult.Futile("There is nowhere to rest here. Not every place will have you."),
            "rest", "sleep", "nap", "sit", "sit down", "lie down", "make camp", "take a rest", "recover");

        registry.RegisterExact((_, _, _) =>
            CommandResult.Futile("Nothing here closes wounds. A potion might, if you are carrying one."),
            "heal", "heal me", "cure me", "bandage");

        registry.RegisterExact((_, session, _) =>
        {
            var character = session.Character;
            session.Write($"HP: {character.HitPoints}/{character.MaxHitPoints}");
            return CommandResult.Done();
        }, "health", "hit points", "hp");

        registry.RegisterExact((engine, session, _) =>
        {
            var names = engine.Sessions.Select(other => other.Character.Name).Order();
            session.Write($"Here in this world: {string.Join(", ", names)}");
            return CommandResult.Done();
        }, "who", "players");

        // What is lying at your feet can be looked at before it is picked up — and
        // so can whatever is standing in the room with you. Someone who types
        // "look at goblin" with a goblin in front of them should not be told they
        // aren't carrying one: every creature in this world was written a
        // description, and until now there was no word that reached it.
        registry.RegisterPrefix((engine, session, argument) =>
        {
            var location = engine.CurrentLocation(session);

            var found = session.Character.FindItemOrEquipped(argument)
                        ?? location?.Items.FirstOrDefault(candidate => candidate.Matches(argument));

            if (found is not null)
            {
                session.Write(found.Description);
                return CommandResult.Done();
            }

            if (location?.Monster is { IsAlive: true } monster && monster.Matches(argument))
            {
                session.Write(monster.Description);
                session.Write($"HP: {monster.HitPoints}/{monster.MaxHitPoints}");
                return CommandResult.Done();
            }

            return CommandResult.Futile($"You aren't carrying a {argument}, and there is no {argument} here.");
        }, "describe", "look at", "examine", "inspect");
    }

    private static void RegisterInventory(CommandRegistry registry)
    {
        registry.RegisterExact((_, session, _) =>
        {
            var character = session.Character;

            session.Write($"Weapon: {character.Weapon?.Name ?? "none equipped"}");
            session.Write($"Armor: {character.Armor?.Name ?? "none equipped"}");
            session.Write(character.Inventory.Count == 0
                ? "Inventory: empty"
                : "Inventory: " + string.Join(", ", character.Inventory.Select(item => item.Name)));

            return CommandResult.Done();
        }, "inventory", "items", "i");

        registry.RegisterPrefix((_, session, argument) =>
        {
            var character = session.Character;
            var item = character.FindItem(argument);

            if (item is null)
            {
                return CommandResult.Futile($"You aren't carrying a {argument}.");
            }

            switch (item.Kind)
            {
                case ItemKind.Weapon:
                    if (character.Weapon is { } oldWeapon) character.Inventory.Add(oldWeapon);
                    character.Weapon = item;
                    break;

                case ItemKind.Armor:
                    if (character.Armor is { } oldArmor) character.Inventory.Add(oldArmor);
                    character.Armor = item;
                    break;

                default:
                    return CommandResult.Futile($"You can't equip the {item.Name}.");
            }

            character.Inventory.Remove(item);
            session.Write($"You equipped the {item.Name}.");
            return CommandResult.Done();
        }, "equip", "wield", "wear", "put on");

        registry.RegisterPrefix((_, session, argument) =>
        {
            var character = session.Character;
            var item = character.FindItem(argument);

            if (item is null)
            {
                return CommandResult.Futile($"You aren't carrying a {argument}.");
            }

            if (item.Kind != ItemKind.Consumable)
            {
                // The room may well know what this thing is for, even though the
                // engine does not.
                return CommandResult.Futile($"Nothing happens when you use the {item.Name}.");
            }

            var healed = Math.Min(item.Definition.HealAmount, character.MaxHitPoints - character.HitPoints);
            character.HitPoints += healed;

            if (item.Definition.ConsumedOnUse)
            {
                character.Inventory.Remove(item);
            }

            session.Write($"You used the {item.Name}. HP: {character.HitPoints}/{character.MaxHitPoints}");
            return CommandResult.Done();
        }, "use", "drink", "eat");

        // Handing a thing over. The engine has no giving in it and nobody in it to
        // give to; this exists so the sentence is a recognised shape, checked
        // against what you are actually holding, and then carried on into the
        // room, where someone may be sitting who will take the thing. Somebody
        // typed "give bone" three times at a woman who trades and was told
        // "Nothing happens."
        registry.RegisterPrefix((_, session, argument) =>
        {
            if (session.Character.FindItemOrEquipped(argument) is { } item)
            {
                return CommandResult.Futile($"There is nobody here who wants the {item.Name}.");
            }

            // "give to the woman" names who, not what. Telling someone they are
            // not carrying a person is the kind of sentence this world has been
            // apologising for all night.
            return CommandResult.Futile(
                $"You aren't holding anything called \"{argument}\". Giving wants the thing, not the person.");
        }, "give", "offer", "hand", "hand over", "hand to");

        registry.RegisterPrefix((engine, session, argument) =>
        {
            var location = engine.CurrentLocation(session);

            if (location is null)
            {
                return CommandResult.Futile($"There is no {argument} here to take.");
            }

            // Standing over what the dead left behind, nobody wants to type seven
            // lines to pick it up.
            if (argument.Trim().Length == 0 || Everything.Contains(StripFillers(TriggerMatcher.Normalize(argument))))
            {
                if (location.Items.Count == 0)
                {
                    return CommandResult.Futile("There is nothing here to take.");
                }

                foreach (var lying in location.Items.ToArray())
                {
                    Take(engine, session, location, lying);
                }

                return CommandResult.Done();
            }

            var item = location.Items.FirstOrDefault(candidate => candidate.Matches(argument));

            if (item is null)
            {
                // Reaching for something already in your hands is a misunderstanding
                // worth clearing up, not a wall.
                if (session.Character.FindItemOrEquipped(argument) is { } carried)
                {
                    return CommandResult.Futile($"You already have the {carried.Name}.");
                }

                return CommandResult.Futile($"There is no {argument} here to take.");
            }

            Take(engine, session, location, item);
            return CommandResult.Done();
        }, "take", "pick up", "get", "grab", "loot", "gather");

        registry.RegisterPrefix((engine, session, argument) =>
        {
            var location = engine.CurrentLocation(session);
            var item = session.Character.FindItem(argument);

            if (location is null || item is null)
            {
                return CommandResult.Futile($"You aren't carrying a {argument}.");
            }

            session.Character.Inventory.Remove(item);
            location.Items.Add(item);
            session.Write($"You drop the {item.Name}.");
            engine.BroadcastToLocation(location.Id, $"{session.Character.Name} drops the {item.Name}.", except: session);
            engine.Emit(GameEvent.For(session, EventType.ItemDropped, ("item", item.Name)));
            return CommandResult.Done();
        }, "drop");
    }

    private static void Take(GameEngine engine, Session session, Location location, Item item)
    {
        location.Items.Remove(item);
        session.Character.Inventory.Add(item);
        session.Write($"You take the {item.Name}.");
        engine.BroadcastToLocation(location.Id, $"{session.Character.Name} takes the {item.Name}.", except: session);
        engine.Emit(GameEvent.For(session, EventType.ItemPickedUp, ("item", item.Name)));
    }

    private static void RegisterCombat(CommandRegistry registry)
    {
        CommandResult Strike(GameEngine engine, Session session, string argument)
        {
            var location = engine.CurrentLocation(session);

            if (location?.Monster is not { IsAlive: true } monster)
            {
                return CommandResult.Futile("There is nothing to attack here.");
            }

            // Naming what is in front of you is the commonest way to say it, and
            // people misspell it with something breathing down their neck. A near
            // miss is taken as the only creature in the room. Anything further off
            // is refused — but told what is actually standing there.
            if (argument.Length > 0 && !monster.Matches(argument))
            {
                var target = StripFillers(TriggerMatcher.Normalize(argument));

                var near = target.Length >= 4
                    && (TriggerMatcher.Distance(target, monster.Name) <= 2
                        || monster.Name.Split(' ').Any(word =>
                            word.Length >= 4 && TriggerMatcher.Distance(target, word) <= 2));

                if (!near)
                {
                    return CommandResult.Futile(
                        $"There is no {argument} here to attack. The {monster.Name} is what is in front of you.");
                }
            }

            engine.Attack(session);
            return CommandResult.Done();
        }

        registry.RegisterExact(Strike, "attack", "fight", "kill", "stab");
        registry.RegisterPrefix(Strike, "attack", "fight", "kill", "stab", "attack the", "kill the");

        // The door.
        //
        // Walking out is the only ending anybody chooses, and it is as final as
        // the other one: the character is finished and nothing comes back in. So
        // it is asked for twice. The first time the door explains exactly what it
        // costs and does not open; the second time it opens. The remembering is
        // character-scoped, so it dies with them and the next life is warned too.
        //
        // Soft words — "leave", "go home" — never commit, however often they are
        // typed. Only words that can mean nothing else do.
        CommandResult AtTheDoor(GameEngine engine, Session session, bool committing)
        {
            var location = engine.CurrentLocation(session);

            if (location is null || !location.IsExit)
            {
                return CommandResult.Futile("Sadly, this is not the exit.");
            }

            if (!session.Character.HasKey)
            {
                return CommandResult.Futile(
                    "The door is locked and you are not carrying the key. The troll in the passage keeps one.");
            }

            if (!committing || session.Character.Conditions.Add(WarnedAtTheDoor))
            {
                session.Write(
                    "Your hand is on it and it gives — unlocked, unbarred, a half-inch of cold daylight and a "
                    + "road going away downhill.\n\n"
                    + "Be sure. This is the edge of the world that was made for you. Nothing was built out "
                    + "there and nothing is waiting, and there is no door back in. Whoever goes through is "
                    + "finished here, carrying out everything they earned. It is not a death — it is the "
                    + "other way out of this valley, and it is the better one.\n\n"
                    + "Say the word again and you go: exit.");

                return CommandResult.Done();
            }

            engine.Leave(session);
            return CommandResult.Done();
        }

        registry.RegisterExact((engine, session, _) => AtTheDoor(engine, session, committing: true),
            "exit", "escape", "walk out", "step through", "through the door", "walk out of the valley");

        registry.RegisterExact((engine, session, _) => AtTheDoor(engine, session, committing: false),
            "leave", "leave here", "go home");
    }

    private static void RegisterSpeech(CommandRegistry registry)
    {
        // Speech is recorded and delivered. The world itself never answers.
        registry.RegisterPrefix((engine, session, argument) =>
        {
            engine.BroadcastToLocation(session.CurrentLocationId,
                $"{session.Character.Name} says: {argument}", except: session);
            session.Write($"You say: {argument}");
            engine.Emit(GameEvent.For(session, EventType.Speech, ("mode", "say"), ("text", argument)));
            return CommandResult.Done();
        }, "say", "speak");

        registry.RegisterPrefix((engine, session, argument) =>
        {
            engine.BroadcastToWorld($"{session.Character.Name} yells: {argument}", except: session);
            session.Write($"You yell: {argument}");
            engine.Emit(GameEvent.For(session, EventType.Speech, ("mode", "yell"), ("text", argument)));
            return CommandResult.Done();
        }, "yell", "shout");

        registry.RegisterPrefix((engine, session, argument) =>
        {
            var split = argument.IndexOf(' ');

            if (split <= 0)
            {
                return CommandResult.Futile("Whisper to whom?");
            }

            var targetName = argument[..split];
            var text = argument[(split + 1)..];
            var target = engine.Sessions.FirstOrDefault(other =>
                string.Equals(other.Character.Name, targetName, StringComparison.OrdinalIgnoreCase));

            if (target is null)
            {
                return CommandResult.Futile($"There is no {targetName} here.");
            }

            target.Write($"{session.Character.Name} whispers: {text}");
            session.Write($"You whisper to {target.Character.Name}: {text}");
            engine.Emit(GameEvent.For(session, EventType.Speech,
                ("mode", "whisper"), ("target", target.CharacterId), ("text", text)));
            return CommandResult.Done();
        }, "whisper", "tell");

        // Addressing whoever is in front of you. The engine has no conversation in
        // it and never will — but this returns Futile, so the command carries on
        // into the room, and a place that has someone worth talking to can answer
        // where the engine cannot. Before this verb existed, "talk to the goblin"
        // was not even a recognised shape of sentence.
        CommandResult Talk(GameEngine engine, Session session, string argument)
        {
            var location = engine.CurrentLocation(session);

            if (location?.Monster is { IsAlive: true } monster)
            {
                return CommandResult.Futile(
                    $"The {monster.Name} does not answer in any language you have.");
            }

            return CommandResult.Futile("There is nobody here to talk to.");
        }

        registry.RegisterPrefix(Talk, "talk to", "talk", "greet", "hail", "ask", "chat to", "chat with", "chat");
        registry.RegisterExact(Talk, "talk", "greet", "hello", "hallo", "hi", "hail", "chat", "anyone there");

        registry.RegisterPrefix((engine, session, argument) =>
        {
            session.Write("You pray.");
            engine.Emit(GameEvent.For(session, EventType.Speech, ("mode", "pray"), ("text", argument)));
            return CommandResult.Done();
        }, "pray");

        registry.RegisterExact((engine, session, _) =>
        {
            session.Write("You pray.");
            engine.Emit(GameEvent.For(session, EventType.Speech, ("mode", "pray"), ("text", "")));
            return CommandResult.Done();
        }, "pray");
    }
}

using Og.Core.Runtime;

namespace Og.Core.Tests;

/// <summary>
/// The other ending. Getting out of this world alive is as final as not getting
/// out of it, and both of those facts have to hold: it must actually end, and it
/// must never happen to somebody who did not mean it.
/// </summary>
public class WalkingOutTests
{
    private static Session AtTheDoorWithAKey(GameEngine engine, Session session)
    {
        var door = engine.World.Locations.First(location => location.IsExit);
        engine.MoveTo(session, door.Id);

        if (engine.World.CreateItem("key") is { } key)
        {
            session.Character.Inventory.Add(key);
        }

        return session;
    }

    [Fact]
    public void TheFirstWordOnlyExplainsAndTheSecondGoesThrough()
    {
        var (engine, _) = WorldFixture.NewEngine();
        var (alice, output) = WorldFixture.Join(engine, "Alice");
        AtTheDoorWithAKey(engine, alice);

        engine.HandleInput(alice, "exit");

        Assert.False(alice.Character.IsDead);
        Assert.Contains(alice, engine.Sessions);
        Assert.Contains("Be sure", output.Text);

        engine.HandleInput(alice, "exit");

        Assert.True(alice.Character.IsDead);
        Assert.True(alice.Character.HasLeft);
        Assert.DoesNotContain(alice, engine.Sessions);
    }

    [Fact]
    public void WhatYouEarnedGoesOutWithYou()
    {
        var (engine, _) = WorldFixture.NewEngine();
        var (alice, _) = WorldFixture.Join(engine, "Alice");
        AtTheDoorWithAKey(engine, alice);

        var door = engine.CurrentLocation(alice)!;

        engine.HandleInput(alice, "exit");
        engine.HandleInput(alice, "exit");

        // Not a death: nothing is dropped, and the floor at the door stays bare.
        Assert.NotEmpty(alice.Character.Inventory);
        Assert.NotNull(alice.Character.Weapon);
        Assert.Empty(door.Items);
    }

    [Fact]
    public void TheDoorKeepsTheNameOfWhoeverGotOut()
    {
        var (engine, _) = WorldFixture.NewEngine();
        var (alice, _) = WorldFixture.Join(engine, "Alice");
        AtTheDoorWithAKey(engine, alice);

        var door = engine.CurrentLocation(alice)!;

        engine.HandleInput(alice, "exit");
        engine.HandleInput(alice, "exit");

        Assert.Contains("Alice", door.Description);
        Assert.DoesNotContain("killed", door.Description);
    }

    [Fact]
    public void ItIsRecordedAsAnEscapeAndNotAsADeath()
    {
        var (engine, events) = WorldFixture.NewEngine();
        var (alice, _) = WorldFixture.Join(engine, "Alice");
        AtTheDoorWithAKey(engine, alice);

        engine.HandleInput(alice, "exit");
        engine.HandleInput(alice, "exit");

        Assert.Single(events.Events, gameEvent => gameEvent.Type == EventType.Escaped);
        Assert.DoesNotContain(events.Events, gameEvent => gameEvent.Type == EventType.Death);
    }

    [Fact]
    public void ASoftWordNeverCommitsHoweverOftenItIsSaid()
    {
        var (engine, _) = WorldFixture.NewEngine();
        var (alice, _) = WorldFixture.Join(engine, "Alice");
        AtTheDoorWithAKey(engine, alice);

        engine.HandleInput(alice, "leave");
        engine.HandleInput(alice, "leave");
        engine.HandleInput(alice, "leave");

        Assert.False(alice.Character.IsDead);
        Assert.Contains(alice, engine.Sessions);
    }

    [Fact]
    public void WithoutAKeyTheDoorNeitherOpensNorWarns()
    {
        var (engine, _) = WorldFixture.NewEngine();
        var (alice, output) = WorldFixture.Join(engine, "Alice");

        var door = engine.World.Locations.First(location => location.IsExit);
        engine.MoveTo(alice, door.Id);

        engine.HandleInput(alice, "exit");
        engine.HandleInput(alice, "exit");

        Assert.False(alice.Character.IsDead);
        Assert.Contains("locked", output.Text);
    }

    [Fact]
    public void ANewLifeIsWarnedAfresh()
    {
        var (engine, _) = WorldFixture.NewEngine();
        var (first, _) = WorldFixture.Join(engine, "Alice");
        AtTheDoorWithAKey(engine, first);

        engine.HandleInput(first, "exit");
        engine.HandleInput(first, "exit");

        var (second, secondOutput) = WorldFixture.Join(engine, "Bob");
        AtTheDoorWithAKey(engine, second);

        engine.HandleInput(second, "exit");

        Assert.False(second.Character.IsDead);
        Assert.Contains("Be sure", secondOutput.Text);
    }
}

